function Arrow({ diagonal=false }) { return <span className="arrow" aria-hidden="true">{diagonal?'↗':'→'}</span>; }
function go(hash) { window.location.hash = hash; }

function EncryptedText({ text, className='' }) {
  const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%&*+-';
  const [frame,setFrame]=useState(()=>text.replace(/\S/g,'·'));
  useEffect(()=>{let reveal=0;const timer=setInterval(()=>{reveal+=1;setFrame(text.split('').map((ch,i)=>ch===' '?' ':i<reveal?ch:chars[Math.floor(Math.random()*chars.length)]).join(''));if(reveal>=text.length)clearInterval(timer)},42);return()=>clearInterval(timer)},[text]);
  return <span className={`encrypted-text ${className}`} aria-label={text}>{frame.split('').map((ch,i)=><span className={ch===text[i]?'decrypted':''} key={i}>{ch}</span>)}</span>;
}

function Globe({ compact=false }) {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;
    let renderer, frame, model, resizeObserver;
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(34, 1, .1, 100);
    camera.position.set(0, 0, 4.5);
    try { renderer = new THREE.WebGLRenderer({ canvas, alpha:true, antialias:true }); }
    catch { return undefined; }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    scene.add(new THREE.AmbientLight(0xb4d5ff, 1.8));
    const key = new THREE.DirectionalLight(0xfff3dc, 3.2); key.position.set(-3, 3, 4); scene.add(key);
    const rim = new THREE.PointLight(0xc66c8a, 18, 10); rim.position.set(2,-1,-2); scene.add(rim);
    const texture = new THREE.TextureLoader().load('/assets/ocean-earth-texture.jpg'); texture.colorSpace = THREE.SRGBColorSpace;
    const draco = new DRACOLoader(); draco.setDecoderPath('/assets/draco/');
    const loader = new GLTFLoader(); loader.setDRACOLoader(draco);
    loader.load('/assets/ocean-earth.glb', gltf => {
      model = gltf.scene;
      const bounds = new THREE.Box3().setFromObject(model); const size = bounds.getSize(new THREE.Vector3()); const center = bounds.getCenter(new THREE.Vector3());
      const scale = 2 / Math.max(size.x,size.y,size.z); model.scale.setScalar(scale); model.position.sub(center.multiplyScalar(scale)); model.rotation.x = Math.PI;
      model.traverse(node => { if (node.isMesh) { node.material = new THREE.MeshStandardMaterial({ map:texture, roughness:.78, metalness:.12 }); node.castShadow=true; node.receiveShadow=true; } });
      scene.add(model);
    }, undefined, () => {});
    const resize = () => { const box=canvas.getBoundingClientRect(); if(!box.width||!box.height)return; renderer.setSize(box.width,box.height,false); camera.aspect=box.width/box.height; camera.updateProjectionMatrix(); };
    resizeObserver = new ResizeObserver(resize); resizeObserver.observe(canvas); resize();
    let pointerDown=false, lastX=0, speed=.0028;
    const down=e=>{pointerDown=true;lastX=e.clientX;canvas.setPointerCapture?.(e.pointerId);};
    const move=e=>{if(pointerDown&&model){model.rotation.y+=(e.clientX-lastX)*.009;lastX=e.clientX;}};
    const up=()=>{pointerDown=false;};
    canvas.addEventListener('pointerdown',down); canvas.addEventListener('pointermove',move); canvas.addEventListener('pointerup',up); canvas.addEventListener('pointercancel',up);
    const onScroll=()=>{speed=.0028 + Math.min(window.scrollY/150000,.008);}; window.addEventListener('scroll',onScroll,{passive:true});
    const tick=()=>{frame=requestAnimationFrame(tick);if(model&&!pointerDown)model.rotation.y+=speed;renderer.render(scene,camera);}; tick();
    return()=>{cancelAnimationFrame(frame);resizeObserver?.disconnect();window.removeEventListener('scroll',onScroll);canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);canvas.removeEventListener('pointercancel',up);texture.dispose();draco.dispose();renderer.dispose();};
  },[]);
  return <div className={`globe-stage ${compact?'globe-compact':''}`}><div className="globe-fallback" aria-hidden="true"><img src="/assets/ocean-earth-texture.jpg" alt=""/></div><canvas ref={canvasRef} aria-label="Rotating interactive 3D Earth; drag to rotate"/><span className="globe-pin pin-a">38°N&nbsp; 24°E</span><span className="globe-pin pin-b">23 DEPTHS</span><span className="globe-hint">DRAG TO ROTATE · SCROLL TO ORBIT</span></div>;
}

function MiniTerminal() {
  const [command,setCommand]=useState(''); const [log,setLog]=useState([{type:'system',text:'dwiz@portfolio:~$ welcome to the tiny dev terminal'},{type:'system',text:'Type help to see commands. One command unlocks the hidden build.'}]); const [unlocked,setUnlocked]=useState(false); const [tries,setTries]=useState(0); const inputRef=useRef(null);
  const submit=e=>{e.preventDefault();const raw=command.trim();if(!raw)return;const cmd=raw.toLowerCase();let response;
    if(cmd==='help')response='commands: help · whoami · stack · git status · guess [3-digit code]';
    else if(cmd==='whoami')response='Dwiz Sharma · software developer · B.Tech @ NIET';
    else if(cmd==='stack')response='Java · Spring Boot · React · Next.js · Python · Three.js';
    else if(cmd==='git status')response='On branch main — 12 project stories ready to explore.';
    else if(cmd==='guess 314'){response='ACCESS GRANTED — you found the little easter egg. ✨';setUnlocked(true);}
    else if(cmd.startsWith('guess')){const n=tries+1;setTries(n);response=n>=3?'LOCKED. Hint: π begins 3.14. Refresh to play again.':'Nope. Hint: it begins with π. Try again.';}
    else response=`command not found: ${raw}. Try help.`;
    setLog(v=>[...v,{type:'input',text:raw},{type:cmd==='guess 314'?'success':'output',text:response}]);setCommand('');
  };
  return <div className="terminal-wrap" onClick={()=>inputRef.current?.focus()}><div className="term-bar"><span className="term-dots"><i/><i/><i/></span><span>dwiz@portfolio — bash</span><span>⌘ K</span></div><div className="term-body" role="log" aria-live="polite">{log.map((line,i)=><div className={`term-line ${line.type}`} key={i}>{line.type==='input'?'$ ':''}{line.text}</div>)}{unlocked&&<div className="secret-unlock">{`{ hidden_level: 'curiosity', status: 'unlocked' }`}</div>}<form onSubmit={submit} className="term-input"><label htmlFor="terminal-command">$</label><input id="terminal-command" ref={inputRef} value={command} onChange={e=>setCommand(e.target.value)} autoComplete="off" spellCheck="false" aria-label="Enter a terminal command"/><button aria-label="Run command">↵</button></form></div></div>;
}

function CodeCrack() {
  const [seq,setSeq]=useState(''); const [answer,setAnswer]=useState(''); const [feedback,setFeedback]=useState('Decode the next value: 2 · 3 · 5 · 8 · 12 · ?'); const [score,setScore]=useState(0); const next=()=>{setSeq('');setAnswer('');setFeedback('Decode the next value: 2 · 3 · 5 · 8 · 12 · ?');};
  const submit=e=>{e.preventDefault();if(answer.trim()==='17'){setFeedback('Correct. The gaps grow by one each time. Nice read.');setScore(s=>s+1);setSeq('solved');}else setFeedback('Not quite — look at the changing gaps. Try again.');};
  return <div className="crack-game"><div className="game-label"><span>MINI LOGIC RUN</span><span>SCORE {String(score).padStart(2,'0')}</span></div><div className="game-grid">{['02','03','05','08','12'].map((x,i)=><span key={x} style={{'--i':i}}>{x}</span>)}<b>?</b></div><p className="game-feedback">{feedback}</p>{seq==='solved'?<button className="game-button" onClick={next}>PLAY AGAIN ↗</button>:<form onSubmit={submit} className="game-answer"><label htmlFor="sequence-answer">NEXT VALUE</label><input id="sequence-answer" value={answer} onChange={e=>setAnswer(e.target.value)} inputMode="numeric" maxLength="2"/><button>CHECK ↗</button></form>}</div>;
}

function RpsGame() {
  const [score,setScore]=useState({you:0,computer:0});
  const [round,setRound]=useState(null);
  const choices=['rock','paper','scissors'];
  const beats={rock:'scissors',paper:'rock',scissors:'paper'};
  const play=(you)=>{const computer=choices[Math.floor(Math.random()*choices.length)];const result=you===computer?'DRAW':beats[you]===computer?'YOU WIN':'COMPUTER WINS';setRound({you,computer,result});if(result==='YOU WIN')setScore(s=>({...s,you:s.you+1}));if(result==='COMPUTER WINS')setScore(s=>({...s,computer:s.computer+1}))};
  const emoji={rock:'✊',paper:'✋',scissors:'✌️'};
  return <div className="rps-game"><div className="game-label"><span>QUICK MATCH</span><span>YOU {score.you} : {score.computer} CPU</span></div><p className="game-prompt">Pick your move.</p><div className="rps-choices">{choices.map(x=><button key={x} onClick={()=>play(x)} aria-label={`Choose ${x}`}><span>{emoji[x]}</span><small>{x.toUpperCase()}</small></button>)}</div><div className="rps-result" aria-live="polite">{round?<>YOU {emoji[round.you]} <b>{round.result}</b> CPU {emoji[round.computer]}</>:'Rock beats scissors · paper beats rock · scissors beats paper'}</div></div>;
}

function ReactionGame() {
  const [phase,setPhase]=useState('idle');const [message,setMessage]=useState('Tap start. Wait for GO, then tap fast.');const [time,setTime]=useState(null);const startedAt=useRef(0);const timer=useRef(null);
  useEffect(()=>()=>clearTimeout(timer.current),[]);
  const start=()=>{clearTimeout(timer.current);startedAt.current=0;setTime(null);setMessage('Wait for the signal…');setPhase('waiting');timer.current=setTimeout(()=>{startedAt.current=performance.now();setPhase('ready');setMessage('GO! TAP NOW')},850+Math.random()*1900)};
  const hit=()=>{if(phase==='idle'||phase==='done'){start();return}if(phase==='waiting'){clearTimeout(timer.current);setPhase('idle');setMessage('Too soon! Wait until GO appears.');return}if(phase==='ready'){const ms=Math.round(performance.now()-startedAt.current);setTime(ms);setMessage(ms<250?'Lightning fast!':ms<400?'Nice reflexes!':'Good warm-up. Try to beat it.');setPhase('done')}};
  return <div className={`reaction-game reaction-${phase}`}><div className="game-label"><span>REFLEX CHECK</span><span>{time!==null?`${time} MS`:phase==='ready'?'NOW!':'READY?'}</span></div><button className="reaction-pad" onClick={hit} aria-live="polite">{phase==='idle'||phase==='done'?'START':phase==='waiting'?'WAIT…':'GO!'}</button><p className="reaction-message">{message}</p></div>;
}

