  if(project.kind==='codealpha') return <div className="art-panel code-art"><div className="art-chip">JAVA · STANDARD LIBRARY</div><pre><i>public static void</i> main(String[] args) {'{'}<br/>&nbsp; Portfolio portfolio = <i>new</i> Portfolio();<br/>&nbsp; portfolio.<b>build</b>(ideas);<br/>&nbsp; System.out.println(<em>"Hello, world!"</em>);<br/>{'}'}<br/><br/><span>✓ compiled successfully</span></pre></div>;
