function ProjectTerminal({project}) {
  const commands=projectCommands[project.id];
  const [mode,setMode]=useState('clone');
  const [copied,setCopied]=useState('');
  const blocks=mode==='clone'?[{title:'Clone repository',code:commands.clone}]:commands.run;
  const copy=async(code,key)=>{try{await navigator.clipboard.writeText(code);setCopied(key);setTimeout(()=>setCopied(''),1600)}catch{setCopied('select-'+key)}};
  return <div className="project-terminal">
    <div className="project-terminal-head"><span className="term-dots"><i/><i/><i/></span><span>PROJECT TERMINAL / {project.id.toUpperCase()}</span><span className="terminal-live-dot">● READY</span></div>
    <div className="terminal-tabs" role="tablist" aria-label="Repository commands"><button role="tab" aria-selected={mode==='clone'} className={mode==='clone'?'selected':''} onClick={()=>{setMode('clone');setCopied('')}}>CLONE</button><button role="tab" aria-selected={mode==='run'} className={mode==='run'?'selected':''} onClick={()=>{setMode('run');setCopied('')}}>RUN LOCALLY{commands.run.length>1?` · ${commands.run.length} TERMINALS`:''}</button></div>
    <div className="terminal-command-list">{blocks.map((block,i)=>{const key=`${mode}-${i}`;return <div className="terminal-command-block" key={key}><div className="terminal-command-meta"><span>{block.title}</span><button onClick={()=>copy(block.code,key)}>{copied===key?'COPIED ✓':copied===`select-${key}`?'SELECT & COPY':'COPY COMMAND'}</button></div><pre><code>{block.code.split('\n').map((line,lineNo)=><span className="command-line" key={lineNo}>{line||' '}</span>)}</code></pre></div>})}</div>
    <div className="terminal-source-note">SOURCE <a href={`${GITHUB}/${project.repo}`} target="_blank" rel="noreferrer">GITHUB.COM/DWIZSHARMA/{project.repo.toUpperCase()} ↗</a></div>
  </div>;
}

